// Generated by `agent-hooks install omp`; do not edit. Re-run it after adding a hook on an
// event not listed below. Each omp hook point dispatches `agent-hooks <Event>` with
// AGENT_HOOKS_AGENT=claude and AGENT_HOOKS_HOST=omp, so catalog rows for claude fire here
// and payloads and results are Claude-shaped. Every payload carries session_id,
// transcript_path and cwd from the omp session.
//
//   session_start          -> SessionStart: context is held and prepended to the first prompt's context
//   agent_start            -> (none): no dispatch; re-arms the session_shutdown Stop fallback
//   before_agent_start     -> UserPromptSubmit: context reaches the model as a hidden agent-hooks-context message
//   tool_call              -> PreToolUse: deny blocks the call with its reason; updatedInput replaces the input; context reaches the model
//   tool_result            -> PostToolUse + PostToolUseFailure: PostToolUseFailure when isError; context and a block reason reach the model; updatedToolOutput replaces the text
//   session_before_compact -> PreCompact: awaited before compaction starts; the result is ignored
//   session_stop           -> Stop: block keeps the turn going with the reason
//   session_shutdown       -> SessionEnd + Stop: SessionEnd; Stop too when no session_stop ran this turn (Ctrl-C, /quit)
//
// Config: ~/.config/agent-hooks/hooks.toml
import { spawn } from "node:child_process";
import { homedir } from "node:os";
import { join } from "node:path";

type Json = Record<string, unknown>;
type OmpContext = {
  cwd?: string;
  sessionManager?: { getSessionId?(): string; getSessionFile?(): string | undefined };
};
type Handler = (event: Json, ctx: OmpContext) => unknown;
type OmpApi = { on(name: string, handler: Handler): void };

const BINARY = join(homedir(), ".cargo", "bin", "agent-hooks");
const CONFIG = join(homedir(), ".config", "agent-hooks", "hooks.toml");
/** Wired agent-hooks events and their deadline in ms: the catalog's slowest hook plus 2 s. */
const TIMEOUT_MS: Record<string, number> = {"PostToolUse":28000,"PostToolUseFailure":28000,"PreCompact":28000,"PreToolUse":28000,"SessionEnd":28000,"SessionStart":28000,"Stop":28000,"UserPromptSubmit":28000};

let startupContext = "";
let stopHandledForTurn = false;

function object(value: unknown): Json | undefined {
  return typeof value === "object" && value !== null && !Array.isArray(value) ? (value as Json) : undefined;
}

function text(value: unknown): string | undefined {
  return typeof value === "string" && value.trim() ? value : undefined;
}

/** The text blocks of a message, a content array, or a plain string. */
function textOf(value: unknown): string {
  if (typeof value === "string") return value;
  if (Array.isArray(value)) {
    return value
      .map((block) => (object(block)?.type === "text" ? (text(object(block)?.text) ?? "") : ""))
      .filter(Boolean)
      .join("\n");
  }
  const content = object(value)?.content;
  if (typeof content === "string") return content;
  if (Array.isArray(content)) return textOf(content);
  return "";
}

function dispatch(event: string, payload: Json): Promise<Json | undefined> {
  const timeout = TIMEOUT_MS[event] ?? 10000;
  return new Promise((resolve) => {
    let resolved = false;
    const finish = (result?: Json) => {
      if (!resolved) {
        resolved = true;
        resolve(result);
      }
    };
    try {
      const child = spawn(BINARY, [event], {
        env: {
          ...process.env,
          AGENT_HOOKS_CONFIG: CONFIG,
          AGENT_HOOKS_AGENT: "claude",
          AGENT_HOOKS_HOST: "omp",
        },
        stdio: ["pipe", "pipe", "inherit"],
      });
      const timer = setTimeout(() => {
        try {
          child.kill("SIGKILL");
        } catch {
          // ignore
        }
        finish(undefined);
      }, timeout);
      let out = "";
      child.stdout.setEncoding("utf-8");
      child.stdout.on("data", (chunk: string) => {
        out += chunk;
      });
      child.on("error", () => {
        clearTimeout(timer);
        finish(undefined);
      });
      child.on("close", (code) => {
        clearTimeout(timer);
        if (code !== 0) return finish(undefined);
        const trimmed = out.trim();
        if (!trimmed) return finish(undefined);
        try {
          finish(JSON.parse(trimmed) as Json);
        } catch {
          finish(undefined);
        }
      });
      child.stdin.end(JSON.stringify(payload));
    } catch {
      finish(undefined);
    }
  });
}

export default function register(pi: OmpApi): void {
  pi.on("session_start", async (_event, ctx) => {
    const payload: Json = {
      session_id: ctx.sessionManager?.getSessionId?.() ?? "",
      transcript_path: ctx.sessionManager?.getSessionFile?.() ?? "",
      cwd: ctx.cwd ?? process.cwd(),
      hook_event_name: "SessionStart",
      source: "startup",
    };
    const res = await dispatch("SessionStart", payload);
    const ctxText = text(res?.context);
    if (ctxText) startupContext = ctxText;
  });

  pi.on("agent_start", () => {
    stopHandledForTurn = false;
  });

  pi.on("before_agent_start", async (event, ctx) => {
    const prompt = textOf(event.message);
    const payload: Json = {
      session_id: ctx.sessionManager?.getSessionId?.() ?? "",
      transcript_path: ctx.sessionManager?.getSessionFile?.() ?? "",
      cwd: ctx.cwd ?? process.cwd(),
      hook_event_name: "UserPromptSubmit",
      prompt,
    };
    const res = await dispatch("UserPromptSubmit", payload);
    const parts: string[] = [];
    if (startupContext) {
      parts.push(startupContext);
      startupContext = "";
    }
    const ctxText = text(res?.context);
    if (ctxText) parts.push(ctxText);
    if (parts.length > 0) {
      return {
        message: {
          role: "user",
          content: [{ type: "text", text: `[agent-hooks context]\n${parts.join("\n\n")}` }],
        },
      };
    }
  });

  pi.on("tool_call", async (event, ctx) => {
    const toolName = typeof event.tool === "string" ? event.tool : "";
    const toolInput = object(event.input) ?? {};
    const payload: Json = {
      session_id: ctx.sessionManager?.getSessionId?.() ?? "",
      transcript_path: ctx.sessionManager?.getSessionFile?.() ?? "",
      cwd: ctx.cwd ?? process.cwd(),
      hook_event_name: "PreToolUse",
      tool_name: toolName,
      tool_input: toolInput,
    };
    const res = await dispatch("PreToolUse", payload);
    if (!res) return;
    const hookSpecific = object(res.hookSpecificOutput);
    const permission = text(hookSpecific?.permission);
    if (permission === "deny") {
      const reason = text(res.reason) ?? "Blocked by agent-hooks";
      return { block: true, reason };
    }
    const updatedInput = object(hookSpecific?.updatedInput);
    const ctxText = text(res.context);
    const out: Json = {};
    if (updatedInput) out.input = updatedInput;
    if (ctxText) out.context = ctxText;
    if (Object.keys(out).length > 0) return out;
  });

  pi.on("tool_result", async (event, ctx) => {
    const toolName = typeof event.tool === "string" ? event.tool : "";
    const toolInput = object(event.input) ?? {};
    const toolOutput = textOf(event.result);
    const isError = Boolean(event.error);
    const eventName = isError ? "PostToolUseFailure" : "PostToolUse";
    const payload: Json = {
      session_id: ctx.sessionManager?.getSessionId?.() ?? "",
      transcript_path: ctx.sessionManager?.getSessionFile?.() ?? "",
      cwd: ctx.cwd ?? process.cwd(),
      hook_event_name: eventName,
      tool_name: toolName,
      tool_input: toolInput,
      tool_output: toolOutput,
      is_error: isError,
    };
    const res = await dispatch(eventName, payload);
    if (!res) return;
    const hookSpecific = object(res.hookSpecificOutput);
    const updatedOutput = text(hookSpecific?.updatedToolOutput);
    const ctxText = text(res.context);
    const reason = text(res.reason);
    const out: Json = {};
    if (updatedOutput !== undefined) out.result = updatedOutput;
    if (ctxText) out.context = ctxText;
    if (reason) out.reason = reason;
    if (Object.keys(out).length > 0) return out;
  });

  pi.on("session_before_compact", async (_event, ctx) => {
    const payload: Json = {
      session_id: ctx.sessionManager?.getSessionId?.() ?? "",
      transcript_path: ctx.sessionManager?.getSessionFile?.() ?? "",
      cwd: ctx.cwd ?? process.cwd(),
      hook_event_name: "PreCompact",
      trigger: "auto",
    };
    await dispatch("PreCompact", payload);
  });

  pi.on("session_stop", async (_event, ctx) => {
    stopHandledForTurn = true;
    const payload: Json = {
      session_id: ctx.sessionManager?.getSessionId?.() ?? "",
      transcript_path: ctx.sessionManager?.getSessionFile?.() ?? "",
      cwd: ctx.cwd ?? process.cwd(),
      hook_event_name: "Stop",
      stop_hook_active: true,
    };
    const res = await dispatch("Stop", payload);
    const reason = text(res?.reason);
    if (reason) {
      return { block: true, reason };
    }
  });

  pi.on("session_shutdown", async (_event, ctx) => {
    const base: Json = {
      session_id: ctx.sessionManager?.getSessionId?.() ?? "",
      transcript_path: ctx.sessionManager?.getSessionFile?.() ?? "",
      cwd: ctx.cwd ?? process.cwd(),
    };
    await dispatch("SessionEnd", { ...base, hook_event_name: "SessionEnd" });
    if (!stopHandledForTurn) {
      await dispatch("Stop", { ...base, hook_event_name: "Stop", stop_hook_active: false });
    }
  });
}
